<div class="row"><label>Tanggal<input type="date" name="entry_date" value="{{ $entry?->entry_date->toDateString() ?? now('Asia/Jakarta')->toDateString() }}" required></label><label>Jenis<select name="entry_type"><option value="expense" @selected($entry?->entry_type === 'expense')>Pengeluaran</option><option value="income" @selected($entry?->entry_type === 'income')>Pemasukan lain</option></select></label></div>
<label>Kategori bebas<input name="category" maxlength="50" value="{{ $entry?->category }}" required></label><label>Nominal (Rp)<input type="number" name="amount" min="1" max="1000000000" value="{{ $entry?->amount }}" required></label><label>Catatan<textarea name="notes" maxlength="1000" required>{{ $entry?->notes }}</textarea></label><label><input type="checkbox" name="not_rental_payment" value="1" style="width:auto"> Jika pemasukan: saya memastikan ini bukan pembayaran sewa yang sudah/akan dicatat melalui verifikasi.</label>
